 const notice=(message,error=false)=>{let n=$('#workspace-notice')||$('#login-error');if($('#admin-dialog[open]')){n=$('#dialog-body>.notice');if(!n){n=document.createElement('p');n.className='notice';n.setAttribute('role','status');$('#dialog-body').prepend(n);}}n.textContent=message;n.classList.toggle('error',error);};
 async function api(url,method='GET',data){const headers={};if(method!=='GET'){headers['Content-Type']='application/json';if(csrf)headers['X-CSRF-Token']=csrf;}const response=await fetch(url,{method,credentials:'same-origin',cache:'no-store',headers,body:data===undefined?undefined:JSON.stringify(data)});let result;try{result=await response.json();}catch{throw Error('Server response could not be read.');}if(!response.ok){const e=Error(result.error||'Request failed');e.status=response.status;throw e;}if(result.csrfToken)csrf=result.csrfToken;return result;}
 function formHandler(form,fn){form.addEventListener('submit',async e=>{e.preventDefault();if(form.dataset.uploading==='true'){notice('Wait for image uploads to finish before saving.',true);return;}const button=e.submitter||form.querySelector('button[type=submit]');if(button)button.disabled=true;try{const message=await fn(Object.fromEntries(new FormData(form)),form);notice(typeof message==='string'?message:'Changes saved.');}catch(err){notice(err.message,true);}finally{if(button)button.disabled=false;}});}
 const field=(name,label,value='',type='text',full=false)=>/^(Image URL|Local image URL|Open Graph image URL)$/.test(label)?imageField(name,label,value):'<label class="'+(full?'full':'')+'">'+esc(label)+(type==='textarea'?'<textarea name="'+name+'" rows="4">'+esc(value)+'</textarea>':'<input name="'+name+'" type="'+type+'" value="'+esc(value)+'"'+(type==='number'?' min="0" step="1"':'')+'>')+'</label>';
 function imageField(name,label,value=''){return '<div class="image-control full"><label>'+esc(label.replace(/URL/g,'upload'))+'<input type="hidden" name="'+esc(name)+'" value="'+esc(value)+'"><input class="image-direct-file" type="file" accept="image/png,image/jpeg,image/webp"></label><div class="image-edit-preview"><img src="'+esc(value||'/assets/hero-lahore-mobile.webp')+'" alt="Image preview"'+(!value?' hidden':'')+'></div><progress max="100" value="0" hidden></progress><p class="image-upload-status muted" role="status"></p><div class="form-grid"><label>Image fitting<select name="'+esc(name)+'-fit"><option value="contain">Contain whole image</option><option value="cover">Fill / crop to frame</option></select></label><label>Horizontal focal point<input name="'+esc(name)+'-x" type="range" min="0" max="100" value="50"></label><label>Vertical focal point<input name="'+esc(name)+'-y" type="range" min="0" max="100" value="50"></label></div><button type="button" class="btn secondary small" data-choose-image>Choose existing image</button> <button type="button" class="btn secondary small" data-remove-image>Remove image</button></div>';}
 function hydrateImageControls(b){document.querySelectorAll('#block-form .image-control').forEach(control=>{const input=control.querySelector('input[type=hidden]'),f=b.type==='existing'?b.fields.find(f=>f.key+'-url'===input.name):input.name==='image'?b.props:b.props.items[Number(input.name.split('-').at(-1))];if(!f)return;control.querySelector('select').value=f.fit||((f.url||'').includes('hero-')?'cover':'contain');control.querySelector('[type=range]').value=f.focalX??50;control.querySelectorAll('[type=range]')[1].value=f.focalY??50;updateImagePreview(control);});}
 function updateImagePreview(control){const image=control.querySelector('img'),input=control.querySelector('input[type=hidden]'),ranges=control.querySelectorAll('[type=range]');image.hidden=!input.value;if(input.value)image.src=input.value;image.style.objectFit=control.querySelector('select')?.value||'contain';image.style.objectPosition=(ranges[0]?.value||50)+'% '+(ranges[1]?.value||50)+'%';}
