 document.addEventListener('click',e=>{const control=e.target.closest('.image-control');if(!control)return;if(e.target.closest('[data-remove-image]')){control.querySelector('input[type=hidden]').value='';updateImagePreview(control);}if(e.target.closest('[data-choose-image]'))action(async()=>{const r=await api('/api/admin/media'),picker=document.createElement('dialog');picker.className='media-picker';picker.innerHTML='<div class="dialog-heading"><h2>Choose an image</h2><button type="button" data-close-picker class="icon-btn" aria-label="Close media picker">×</button></div><div class="media-grid">'+[...r.media.map(m=>({url:'/media/'+m.id+'.webp',name:m.name})),...r.assets].map(m=>'<button type="button" class="media-card" data-image-url="'+esc(m.url)+'"><img src="'+esc(m.url)+'" alt="'+esc(m.name)+'" loading="lazy"><span>'+esc(m.name)+'</span></button>').join('')+'</div>';document.body.append(picker);picker.querySelector('[data-close-picker]').onclick=()=>picker.close();picker.addEventListener('close',()=>picker.remove());picker.querySelectorAll('[data-image-url]').forEach(b=>b.onclick=()=>{control.querySelector('input[type=hidden]').value=b.dataset.imageUrl;updateImagePreview(control);picker.close();});picker.showModal();});});
 const select=(name,label,value,options)=>'<label>'+esc(label)+'<select name="'+name+'">'+options.map(v=>'<option'+(String(v)===String(value)?' selected':'')+'>'+esc(v)+'</option>').join('')+'</select></label>';
