 $('#dialog-close').addEventListener('click',()=>$('#admin-dialog').close());const closeAdminNav=()=>{document.body.classList.remove('nav-open');$('#sidebar-toggle').setAttribute('aria-expanded','false');};$('#sidebar-toggle').addEventListener('click',()=>{const open=document.body.classList.toggle('nav-open');$('#sidebar-toggle').setAttribute('aria-expanded',String(open));if(open)$('#admin-sidebar a')?.focus();});document.addEventListener('keydown',e=>{if(e.key==='Escape'){const wasOpen=document.body.classList.contains('nav-open');closeAdminNav();$('.admin-account').open=false;if(wasOpen)$('#sidebar-toggle').focus();}if(e.key==='Tab'&&document.body.classList.contains('nav-open')&&innerWidth<=760){const items=[$('#sidebar-toggle'),...document.querySelectorAll('#admin-sidebar a[href]')],first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});document.addEventListener('click',e=>{if(!e.target.closest('.admin-account'))$('.admin-account').open=false;if(document.body.classList.contains('nav-open')&&!e.target.closest('#admin-sidebar,#sidebar-toggle'))closeAdminNav();});addEventListener('resize',()=>{if(innerWidth>760)closeAdminNav();});
