 async function load(){identity=await api('/api/admin/me');$('#admin-name').textContent=identity.user.name+' · '+identity.role;$('#admin-navigation').innerHTML=(identity.mfaVerified?[...new Set([...identity.permissions,'security'])]:['security']).map(p=>'<a href="/admin/'+p+'"'+(p===section?' aria-current="page"':'')+'><span class="nav-icon">'+icons[p]+'</span>'+labels[p]+'</a>').join('');$('#workspace-title').textContent=labels[section]||'Workspace';$('#workspace-description').textContent=descriptions[section]||'';$('#workspace-actions').replaceChildren();await views[section]();}
 const views={};
 const chartColors=['#ff6900','#2563eb','#14a38b','#64748b','#dc5667','#9b70cf'];
 function lineChart(days,key,title,color,id){const values=days.map(d=>Number(d[key])||0),empty=values.every(v=>v===0),high=Math.max(0,...values),low=Math.min(0,...values),max=empty?1:Math.max(4,Math.ceil(high/4)*4),min=Math.min(0,Math.floor(low/4)*4),w=640,h=230,left=64,right=20,top=20,bottom=42,plotW=w-left-right,plotH=h-top-bottom,x=i=>left+i*plotW/Math.max(1,days.length-1),y=v=>top+(max-v)*plotH/(max-min),format=v=>key==='receipts'?money(v):String(Math.round(v)),points=values.map((v,i)=>x(i).toFixed(1)+','+y(v).toFixed(1)),path='M'+points.join(' L'),area=path+' L'+x(days.length-1)+','+y(0)+' L'+x(0)+','+y(0)+' Z';let svg='<svg class="trend-svg" viewBox="0 0 '+w+' '+h+'" role="img" aria-label="'+esc(title)+'. '+(empty?'No records in this period.':'Daily actual records; full values in the data table.')+'"><defs><linearGradient id="'+id+'" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="'+color+'" stop-opacity=".18"/><stop offset="100%" stop-color="'+color+'" stop-opacity=".015"/></linearGradient></defs>';
  for(let i=0;i<5;i++){const value=min+(max-min)*i/4;if(empty&&i!==0)continue;svg+='<line x1="'+left+'" x2="'+(w-right)+'" y1="'+y(value)+'" y2="'+y(value)+'" stroke="#edf1f4"/><text x="'+(left-10)+'" y="'+(y(value)+4)+'" text-anchor="end" class="chart-label">'+esc(key==='receipts'?(Math.abs(value)>=1000?(value/1000).toFixed(0)+'k':Math.round(value)):Math.round(value))+'</text>';}
  svg+='<path d="'+area+'" fill="url(#'+id+')"/><path d="'+path+'" fill="none" stroke="'+color+'" stroke-width="2.8" stroke-linejoin="round" stroke-linecap="round"/>';
  days.forEach((d,i)=>{svg+='<circle class="chart-point" tabindex="0" cx="'+x(i)+'" cy="'+y(values[i])+'" r="3.5" fill="'+color+'"><title>'+esc(d.day+': '+format(values[i]))+'</title></circle>';if(i===0||i===days.length-1||i%4===0)svg+='<text x="'+x(i)+'" y="'+(h-12)+'" text-anchor="middle" class="chart-label">'+esc(new Date(d.day+'T00:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'UTC'}))+'</text>';});svg+='</svg>';
  return '<section class="panel trend-panel"><div class="panel-heading"><div><p class="admin-kicker">LAST 14 DAYS · PAKISTAN TIME</p><h2>'+esc(title)+'</h2></div><span class="chart-total">'+esc(key==='receipts'?money(values.reduce((a,b)=>a+b,0)):values.reduce((a,b)=>a+b,0))+'</span></div>'+svg+'<p class="chart-caption">'+(empty?'No '+(key==='receipts'?'recorded payments or refunds':'booking requests')+' in this period.':key==='receipts'?'Actual payments minus refunds; quotations are excluded.':'New rental requests recorded each day.')+'</p><details class="chart-data"><summary>View daily values</summary>'+table(['Date',key==='receipts'?'Net receipts':'Requests'],days.map((d,i)=>'<tr><td>'+esc(d.day)+'</td><td>'+esc(format(values[i]))+'</td></tr>'))+'</details></section>';
 }
 function statusDonut(counts){const statuses=['Pending','Confirmed','Active','Completed','Cancelled','Rejected'],total=Number(counts.total)||0;let offset=0;const slices=statuses.map((s,i)=>{const start=offset;offset+=total?(Number(counts[s.toLowerCase()])||0)*100/total:0;return chartColors[i]+' '+start+'% '+offset+'%';});return '<section class="panel status-panel"><div class="panel-heading"><div><p class="admin-kicker">ALL RENTAL REQUESTS</p><h2>Booking distribution</h2></div></div><div class="status-visual"><div class="status-donut" role="img" aria-label="'+esc(statuses.map(s=>s+': '+(counts[s.toLowerCase()]||0)).join(', '))+'" style="background:'+(total?'conic-gradient('+slices.join(',')+')':'#edf1f4')+'"><div><strong>'+total+'</strong><span>Total requests</span></div></div><div class="status-legend">'+statuses.map((s,i)=>'<div><span class="legend-dot" style="background:'+chartColors[i]+'"></span><span>'+s+'</span><strong>'+(counts[s.toLowerCase()]||0)+'</strong></div>').join('')+'</div></div>'+(total?'':'<p class="chart-caption">Your first rental request will appear here.</p>')+'</section>';}
 views.dashboard=async()=>{const r=await api('/api/admin/dashboard'),c=r.counts,days=r.analytics.days;$('#workspace-content').innerHTML='<section class="dashboard-welcome"><div><p class="admin-kicker">YOUR BUSINESS AT A GLANCE</p><h2>Welcome, '+esc(identity.user.name.split(' ')[0])+'.</h2><p>'+c.pending+' pending request'+(c.pending===1?'':'s')+' awaiting review · '+new Intl.DateTimeFormat('en-GB',{dateStyle:'long',timeZone:'Asia/Karachi'}).format(new Date())+'</p></div><span class="live-indicator"><i></i> Live database</span></section><div class="stats-grid dashboard-stats">'+[['Customers',c.customers,'Registered customer accounts'],['Fleet vehicles',c.cars,'Archived vehicles excluded'],['Available now',c.available,'Ready and not currently rented'],['Pending requests',c.pending,'Awaiting a business decision'],['Confirmed bookings',c.confirmed,'Availability and terms approved'],['Active rentals',c.active,'Currently on rental'],['Completed rentals',c.completed,'Recorded completed journeys'],['Cancelled bookings',c.cancelled,'Cancelled rental requests'],['Recorded net receipts',money(c.revenue),'Actual payments minus refunds']].filter((_,i)=>[0,1,3,8].includes(i)).map(([l,v,n],i)=>'<article class="stat-card"><div class="stat-top"><span>'+l+'</span><span class="stat-icon">'+['♙','◇','◷','₨'][i]+'</span></div><strong>'+esc(v)+'</strong><small>'+n+'</small></article>').join('')+'</div><div class="operational-stats">'+[['Available now',c.available],['Confirmed',c.confirmed],['Active rentals',c.active],['Completed',c.completed],['Cancelled',c.cancelled]].map(([l,n])=>'<div><span>'+l+'</span><strong>'+n+'</strong></div>').join('')+'</div><div class="analytics-grid">'+lineChart(days,'requests','Booking activity','#ff6900','booking-gradient')+lineChart(days,'receipts','Net receipts','#2563eb','receipt-gradient')+'</div><div class="workspace-grid"><section class="panel"><div class="panel-heading"><h2>Recent requests</h2>'+(identity.permissions.includes('bookings')?'<a class="panel-link" href="/admin/bookings">View all →</a>':'')+'</div>'+bookingTable(r.recentBookings)+'</section>'+statusDonut(c)+'<section class="panel"><h2>Recent customers</h2>'+(r.recentCustomers.length?r.recentCustomers.map(u=>'<div class="audit-row">'+esc(u.name)+'<small>'+esc(new Date(u.created_at).toLocaleString())+'</small></div>').join(''):empty('No customers yet'))+'</section><section class="panel"><h2>Activity history</h2>'+(r.activity.length?r.activity.map(a=>'<div class="audit-row">'+esc(a.action)+'<small>'+esc(a.resource)+' · '+esc(new Date(a.created_at).toLocaleString())+'</small></div>').join(''):empty('No activity yet'))+'</section><section class="panel full"><h2>Fleet · next 24 hours</h2>'+table(['Vehicle','State'],r.fleet.map(c=>'<tr><td>'+esc(c.name)+'</td><td>'+pill(c.status)+'</td></tr>'))+'</section></div>';if(identity.permissions.includes('availability')){$('#workspace-content>.workspace-grid').insertAdjacentHTML('afterbegin','<section class="panel"><div class="panel-heading"><h2>Operations reminders</h2><a class="panel-link" href="/admin/availability">Open calendar →</a></div>'+((r.reminders.overdue.length||r.reminders.pickups.length)?[...r.reminders.overdue.map(b=>'<p class="overdue-text">Return follow-up: '+esc(b.reference+' · '+b.carName)+'</p>'),...r.reminders.pickups.map(b=>'<p>Pickup due: '+esc(b.reference+' · '+b.carName)+' · '+esc(new Date(b.pickupAt).toLocaleString())+'</p>')].join(''):'<p class="muted">No overdue rentals or confirmed pickups in the next 24 hours.</p>')+'<form id="dashboard-availability" class="toolbar"><label>From<input type="date" name="start" required></label><label>Through<input type="date" name="end" required></label><button class="btn secondary" type="submit">Search fleet availability</button></form></section>');formHandler($('#dashboard-availability'),async d=>{if(d.end<d.start)throw Error('Return must be after pickup.');location.assign('/admin/availability?'+new URLSearchParams(d));});}bindBookings();$('#workspace-actions').innerHTML=identity.permissions.includes('bookings')?'<a class="btn" href="/admin/bookings">Review requests →</a>':'';};
 function bookingTable(rows){return rows.length?table(['Reference / vehicle','Pickup','Status','Quote',''],rows.map(b=>'<tr><td><strong>'+esc(b.reference)+'</strong><br>'+esc(b.carName)+'</td><td>'+esc(new Date(b.pickupAt).toLocaleDateString())+'</td><td>'+pill(b.status)+'</td><td>'+(b.quotedPrice===null?'Awaiting quote':money(b.quotedPrice))+'</td><td>'+(identity.permissions.includes('bookings')?'<button class="btn secondary small" data-booking="'+b.id+'">Review</button>':'')+'</td></tr>')):empty('No rental requests','New customer requests will appear here with a Pending status.');}
