 async function bookingDetails(id){const r=await api('/api/admin/bookings/'+id),b=r.booking;dialog(b.reference,'<div class="workspace-grid"><div><img src="'+esc(b.carImage)+'" alt="'+esc(b.carName)+'" style="width:100%;max-height:220px;object-fit:contain"><h3>'+esc(b.carName)+'</h3><dl class="data-list">'+[['Customer',r.customer.name],['Email',r.customer.email],['Contact',b.phone],['Pickup',new Date(b.pickupAt).toLocaleString()],['Return',new Date(b.returnAt).toLocaleString()],['Location',b.location],['Duration',b.days+' days'],['Estimate',money(b.estimate)],['Additional requests',b.requests||'None']].map(([k,v])=>'<div><dt>'+k+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl></div><form id="booking-decision">'+select('status','Rental status',b.status,['Pending','Confirmed','Active','Completed','Cancelled','Rejected'])+field('quotedPrice','Final quotation (PKR)',b.quotedPrice??'','number')+field('prepaidAmount','Recorded prepaid rental amount (legacy field)',b.prepaidAmount,'number')+field('ownerNote','Customer-visible terms / cancellation reason',b.ownerNote,'textarea')+field('internalNote','Internal note — not visible to customer',r.internalNote,'textarea')+'<button class="btn" type="submit">Save decision</button></form></div><section class="panel"><h3>Offline payments and refunds</h3><p class="muted">Record a receipt after confirming actual payment. This does not charge a customer.</p>'+table(['Type','Amount','Receipt'],r.payments.map(p=>'<tr><td>'+esc(p.kind)+'</td><td>'+money(p.amount)+'</td><td>'+esc(p.reference)+'</td></tr>'))+'<form id="record-payment" class="form-grid">'+select('kind','Record type','payment',['payment','refund'])+field('amount','Amount (PKR)','','number')+field('reference','Unique receipt reference')+field('note','Notes')+'<button class="btn secondary" type="submit">Record receipt</button></form></section><h3>Status history</h3>'+r.events.map(e=>'<div class="audit-row">'+pill(e.status)+' '+esc(e.note)+'<small>'+esc(new Date(e.createdAt).toLocaleString())+'</small></div>').join(''));formHandler($('#booking-decision'),async d=>{if(d.status==='Completed'&&b.status!=='Completed'){if(!confirm('Confirm this vehicle has actually been returned and checked in?'))return;d.confirmReturn=true;}await api('/api/admin/bookings/'+id,'PATCH',d);$('#admin-dialog').close();await views[section]();});formHandler($('#record-payment'),async d=>{if(!confirm('Record this actual offline receipt/refund?'))return;await api('/api/admin/bookings/'+id+'/payments','POST',d);await bookingDetails(id);});}
 views.fleet=async()=>{const r=await api('/api/admin/fleet');$('#workspace-actions').innerHTML='<button class="btn" id="new-car">Add vehicle +</button>';$('#new-car').onclick=()=>carForm();$('#workspace-content').innerHTML='<section class="panel">'+table(['Image','Vehicle / reference','Category','Daily rate','Status',''],r.vehicles.map(c=>'<tr><td><img src="'+esc(c.image)+'" alt="'+esc(c.make+' '+c.name)+'"></td><td><strong>'+esc(c.make+' '+c.name)+'</strong><br>'+esc(c.reference)+'</td><td>'+esc(c.category)+'</td><td>'+money(c.rate)+'</td><td>'+pill(c.status)+'</td><td><button class="btn secondary small" data-car="'+c.id+'">Edit</button></td></tr>'))+'</section>';document.querySelectorAll('[data-car]').forEach(b=>b.onclick=()=>carForm(r.vehicles.find(c=>c.id===Number(b.dataset.car))));};
 function carForm(c={status:'available',category:'Economy',transmission:'Auto',seats:5,fuel:'Petrol'}){dialog(c.id?'Edit vehicle':'Add vehicle','<form id="car-form"><div class="form-grid">'+field('make','Make',c.make)+field('name','Model',c.name)+field('year','Year',c.year??'','number')+field('reference','Unique internal reference',c.reference)+field('registration','Registration (internal)',c.registration)+select('category','Category',c.category,['Economy','Sedan','SUV','Premium','MPV'])+field('seats','Seats',c.seats,'number')+select('transmission','Transmission',c.transmission,['Auto','Manual'])+field('fuel','Fuel type',c.fuel)+field('rate','Daily rate (PKR)',c.rate,'number')+field('weeklyRate','Weekly rate (PKR)',c.weeklyRate,'number')+field('monthlyRate','Monthly rate (PKR)',c.monthlyRate,'number')+field('deposit','Refundable deposit (PKR)',c.deposit||0,'number')+select('status','Availability state',c.status,['available','unavailable','maintenance','archived'])+field('description','Description',c.description,'textarea',true)+field('features','Features — one per line',(c.features||[]).join('\n'),'textarea',true)+'<input type="hidden" name="images" value="'+esc((c.images||[c.image].filter(Boolean)).join('\n'))+'"><div class="full vehicle-image-previews" id="vehicle-image-previews"></div>'+'<label class="full">Upload vehicle photos (up to 20 MB each; optimized before upload)<input type="file" id="car-photos" accept="image/png,image/jpeg,image/webp" multiple></label>'+check('featured','Feature on homepage car-grid sections',c.featured)+'</div><p class="muted">Archiving preserves historical rental requests. Each record represents one physical vehicle/unit.</p><div class="form-actions"><button class="btn" type="submit">Save vehicle</button></div></form>');const refreshPhotos=()=>{$('#vehicle-image-previews').innerHTML=$('#car-form [name=images]').value.split('\n').filter(Boolean).map((src,i)=>'<div><img src="'+esc(src)+'" alt="Vehicle photo '+(i+1)+'"><button type="button" class="btn secondary small" data-remove-photo="'+i+'">Remove</button></div>').join('');document.querySelectorAll('[data-remove-photo]').forEach(button=>button.onclick=()=>{const input=$('#car-form [name=images]'),images=input.value.split('\n').filter(Boolean);images.splice(Number(button.dataset.removePhoto),1);input.value=images.join('\n');refreshPhotos();});};refreshPhotos();$('#car-photos').onchange=()=>action(async()=>{const photoInput=$('#car-photos'),photoForm=$('#car-form'),save=photoForm.querySelector('button[type=submit]'),selected=[...photoInput.files],existing=photoForm.elements.images.value.split('\n').filter(Boolean);if(existing.length+selected.length>10)throw Error('Keep up to 10 photos per vehicle. Remove a photo first.');photoInput.disabled=true;photoForm.dataset.uploading='true';save.disabled=true;try{for(const file of selected){const r=await upload(file,file.name,'fleet');const input=$('#car-form [name=images]');input.value+=(input.value?'\n':'')+r.url;}refreshPhotos();notice('Images uploaded. Save the vehicle to attach them.');}finally{photoInput.disabled=false;photoForm.dataset.uploading='false';save.disabled=false;photoInput.value='';}});formHandler($('#car-form'),async(d,form)=>{if(d.status==='archived'&&c.status!=='archived'&&!confirm('Archive this vehicle while preserving historical bookings?'))return;d.images=d.images.split('\n').map(x=>x.trim()).filter(Boolean);d.features=d.features.split('\n').map(x=>x.trim()).filter(Boolean);d.featured=form.elements.featured.checked;await api('/api/admin/fleet'+(c.id?'/'+c.id:''),c.id?'PATCH':'POST',d);$('#admin-dialog').close();await views.fleet();});}
 views.customers=async()=>{const render=rows=>rows.length?table(['Customer','Contact','Joined','State',''],rows.map(c=>'<tr><td><strong>'+esc(c.name)+'</strong><br>'+esc(c.email)+'</td><td>'+esc(c.phone)+'</td><td>'+esc(new Date(c.created_at).toLocaleDateString())+'</td><td>'+pill(c.suspended?'Suspended':'Active')+'</td><td><button class="btn secondary small" data-customer="'+c.id+'">Details</button></td></tr>')):empty('No customers');const r=await api('/api/admin/customers');$('#workspace-content').innerHTML='<section class="panel"><form id="customer-search" class="toolbar"><input name="q" aria-label="Search customers" placeholder="Name or email"><button class="btn secondary" type="submit">Search</button></form><div id="customer-list">'+render(r.customers)+'</div></section>';const bind=()=>document.querySelectorAll('[data-customer]').forEach(b=>b.onclick=()=>action(async()=>{const r=await api('/api/admin/customers/'+b.dataset.customer),c=r.customer;dialog(c.name,'<p>'+esc(c.email)+' · '+esc(c.phone)+'</p><p>Verified email: '+(c.emailVerified?'Yes':'No')+'</p><form id="customer-form">'+field('note','Support notes',c.note,'textarea')+check('suspended','Suspend this customer account',c.suspended)+'<button class="btn" type="submit">Save account changes</button></form><h3 style="margin-top:32px">Booking history</h3>'+bookingTable(r.bookings));bindBookings();formHandler($('#customer-form'),async(d,form)=>{if(!confirm('Confirm customer account and support-note changes?'))return;await api('/api/admin/customers/'+c.id,'PATCH',{note:d.note,suspended:form.elements.suspended.checked,confirm:true});$('#admin-dialog').close();await views.customers();});}));bind();formHandler($('#customer-search'),async d=>{const r=await api('/api/admin/customers?q='+encodeURIComponent(d.q));$('#customer-list').innerHTML=render(r.customers);bind();});};
 async function upload(file,name,category,replaceId,onProgress){if(!file||!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>20000000)throw Error('Choose a PNG, JPEG or WebP image up to 20 MB.');let source=file;if(file.size>950000){const bitmap=await createImageBitmap(file);try{if(bitmap.width*bitmap.height>40000000)throw Error('Choose an image below 40 megapixels.');const scale=Math.min(1,1920/bitmap.width,1920/bitmap.height),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);for(const quality of [.84,.7,.55,.4]){source=await new Promise(r=>canvas.toBlob(r,'image/webp',quality));if(source&&source.size<950000)break;}if(!source||source.size>1000000)throw Error('Image is too complex. Please choose a smaller image.');}finally{bitmap.close();}}const image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Image could not be read.'));reader.readAsDataURL(source);});return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST','/api/admin/media');xhr.setRequestHeader('Content-Type','application/json');if(csrf)xhr.setRequestHeader('X-CSRF-Token',csrf);xhr.timeout=55000;xhr.upload.onprogress=e=>{if(e.lengthComputable)onProgress?.(Math.round(e.loaded/e.total*100));};xhr.onerror=()=>reject(Error('Image upload failed. Check your connection and retry.'));xhr.ontimeout=()=>reject(Error('Image upload timed out. Please retry.'));xhr.onload=()=>{let result;try{result=JSON.parse(xhr.responseText);}catch{return reject(Error('Image service response could not be read.'));}if(xhr.status<200||xhr.status>=300)return reject(Error(result.error||'Image upload failed.'));if(result.csrfToken)csrf=result.csrfToken;resolve(result);};xhr.send(JSON.stringify({image,name,category,alt:name,replaceId,confirm:Boolean(replaceId)}));});}

 views.media=async()=>{const r=await api('/api/admin/media');$('#workspace-content').innerHTML='<section class="panel"><h2>Add images</h2><form id="media-upload" class="form-grid">'+field('name','Image name')+field('category','Category','general')+'<label class="full">PNG, JPEG or WebP (up to 20 MB each; optimized before upload)<input id="media-files" type="file" accept="image/png,image/jpeg,image/webp" required multiple></label><button class="btn" type="submit">Upload & optimize</button></form></section><div class="media-grid">'+r.media.map(m=>'<article class="media-card"><img src="/media/'+m.id+'-small.webp" alt="'+esc(m.alt)+'"><h3>'+esc(m.name)+'</h3><p class="muted">'+m.width+' × '+m.height+' · '+esc(m.category)+'</p><code>/media/'+m.id+'.webp</code><p><button class="btn secondary small" data-media="'+m.id+'">Edit details</button></p></article>').join('')+'</div><section class="panel" style="margin-top:24px"><h2>Original website assets</h2><p class="muted">Existing supplied images are preserved. Use Choose existing image in the page editor to reuse them.</p><div class="media-grid">'+r.assets.map(a=>'<article class="media-card"><img src="'+esc(a.url)+'" alt="'+esc(a.name)+'"><code>'+esc(a.url)+'</code></article>').join('')+'</div></section>';formHandler($('#media-upload'),async d=>{for(const file of [...$('#media-files').files].slice(0,10))await upload(file,d.name||file.name,d.category);await views.media();});document.querySelectorAll('[data-media]').forEach(b=>b.onclick=()=>{const m=r.media.find(m=>m.id===b.dataset.media);dialog('Image details','<form id="media-details">'+field('name','Name',m.name)+field('category','Category',m.category)+field('alt','Alt description',m.alt)+'<div class="form-actions"><button class="btn" type="submit">Save details</button><button class="btn danger" id="delete-media" type="button">Delete unused image</button></div></form><label>Replace this image in all references<input id="replace-media" type="file" accept="image/png,image/jpeg,image/webp"></label><p class="muted">Variants: /media/'+m.id+'-small.webp (640 px) and /media/'+m.id+'.webp (up to 1920 px).</p>');formHandler($('#media-details'),async d=>{await api('/api/admin/media/'+m.id,'PATCH',d);$('#admin-dialog').close();await views.media();});$('#delete-media').onclick=()=>action(async()=>{if(!confirm('Delete this unused image? References in pages, versions or vehicles will prevent deletion.'))return;await api('/api/admin/media/'+m.id,'DELETE',{confirm:true});$('#admin-dialog').close();await views.media();});$('#replace-media').onchange=()=>action(async()=>{if(!confirm('Replace this image for every page and vehicle using its URL?'))return;await upload($('#replace-media').files[0],m.name,m.category,m.id);$('#admin-dialog').close();await views.media();});});};
 // The page builder, settings and security views are defined below.
 views.pages=async()=>{const r=await api('/api/admin/pages');window.mzgTemplates=r.templates;$('#workspace-content').innerHTML='<div class="toolbar"><label style="margin:0;flex:1">Website page<select id="page-choice">'+r.pages.map(p=>'<option value="'+p.slug+'">'+esc(p.file)+'</option>').join('')+'</select></label></div><div id="page-editor"></div>';$('#page-choice').onchange=()=>action(()=>loadPage($('#page-choice').value));await loadPage('index');};
 async function loadPage(slug){const r=await api('/api/admin/pages/'+slug);pageState=r.page;pageState.revisions=r.revisions;selectedBlock=0;renderEditor();}
 function renderEditor(){const p=pageState;$('#page-editor').innerHTML='<div class="toolbar"><button class="btn" id="save-draft">Save draft</button><button class="btn secondary" id="preview-page">Save & preview</button><button class="btn secondary" id="publish-page">Publish</button><button class="btn secondary" id="versions-page">Published versions</button><span class="muted">Revision '+p.revision+'</span></div><div class="editor-layout"><section class="panel"><h2>Sections</h2><div class="section-list">'+p.content.blocks.map((b,i)=>'<div class="section-item'+(i===selectedBlock?' active':'')+'"><button data-select-block="'+i+'">'+esc(b.label||b.type)+(b.hidden?' · hidden':'')+'</button><div class="section-actions"><button title="Move up" data-move="'+i+'" data-direction="-1">↑</button><button title="Move down" data-move="'+i+'" data-direction="1">↓</button></div></div>').join('')+'</div><label style="margin-top:20px">Add a section<select id="template-choice">'+window.mzgTemplates.map(t=>'<option>'+t+'</option>').join('')+'</select></label><button id="add-block" class="btn secondary">Add section +</button><p class="muted" style="margin-top:16px">Original sections reorder within their existing layout wrapper. New template sections appear after existing content.</p></section><section class="panel" id="block-editor"></section></div>';document.querySelectorAll('[data-select-block]').forEach(b=>b.onclick=()=>{captureBlock();selectedBlock=Number(b.dataset.selectBlock);renderEditor();});document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{captureBlock();const from=Number(b.dataset.move),to=from+Number(b.dataset.direction);if(to<0||to>=p.content.blocks.length)return;[p.content.blocks[from],p.content.blocks[to]]=[p.content.blocks[to],p.content.blocks[from]];selectedBlock=to;renderEditor();});$('#add-block').onclick=()=>{captureBlock();p.content.blocks.push({id:crypto.randomUUID(),type:$('#template-choice').value,label:'New '+$('#template-choice').value,hidden:false,background:'white',props:{title:'Your new section',text:'',image:'',alt:'',button:'Explore our fleet',url:'/fleet.html',alignment:'left',items:[],carIds:[]}});selectedBlock=p.content.blocks.length-1;renderEditor();};$('#save-draft').onclick=()=>action(saveDraft);$('#preview-page').onclick=()=>action(async()=>{await saveDraft();dialog('Draft preview','<iframe class="preview-frame" title="Website draft preview" sandbox="allow-same-origin" src="/cms-preview/'+p.slug+'"></iframe>');});$('#publish-page').onclick=()=>action(async()=>{await saveDraft();if(!confirm('Publish this saved draft to the public website?'))return;const r=await api('/api/admin/pages/'+p.slug+'/publish','POST',{revision:pageState.revision,confirm:true});pageState=r.page;await loadPage(p.slug);notice('Changes published to the public website.');});$('#versions-page').onclick=()=>action(async()=>{const r=await api('/api/admin/pages/'+p.slug);dialog('Published versions',r.revisions.length?table(['Version','Published history',''],r.revisions.map(v=>'<tr><td>'+v.id+'</td><td>'+esc(new Date(v.created_at).toLocaleString())+'</td><td><button class="btn secondary small" data-rollback="'+v.id+'">Restore</button></td></tr>')):empty('No previous published version'));document.querySelectorAll('[data-rollback]').forEach(b=>b.onclick=()=>action(async()=>{if(!confirm('Publish this previous version and replace the current draft?'))return;await api('/api/admin/pages/'+p.slug+'/rollback','POST',{revision:r.page.revision,version:Number(b.dataset.rollback),confirm:true});$('#admin-dialog').close();await loadPage(p.slug);notice('Previous version restored.');}));});renderBlock();}
 function renderBlock(){const b=pageState.content.blocks[selectedBlock];if(!b){$('#block-editor').innerHTML=empty('Choose a section');return;}let content='<h2>'+esc(b.label||b.type)+'</h2><form id="block-form">'+check('hidden','Hide section',b.hidden)+select('background','Background',b.background,['original','white','light','dark','orange']);if(b.type==='existing')content+=select('alignment','Text alignment',b.alignment||'original',['original','left','center','right'])+b.fields.map(f=>field(f.key,f.tag==='img'?'Image alt description':f.tag.toUpperCase()+' text',f.text,f.text.length>120?'textarea':'text')+(f.url!==undefined?field(f.key+'-url',f.tag==='img'?'Image URL':'Button/link destination',f.url):'')).join('');else{const p=b.props;content+=field('title','Heading',p.title)+field('text','Body text',p.text,'textarea')+field('image','Local image URL',p.image)+field('alt','Image alt description',p.alt)+field('button','Button label',p.button)+field('url','Button destination',p.url)+select('alignment','Text alignment',p.alignment,['left','center','right'])+field('carIds','Featured car IDs (comma separated)',(p.carIds||[]).join(',') )+'<h3>Template items</h3><div id="template-items">'+(p.items||[]).map((x,i)=>'<div class="item-editor" data-item="'+i+'">'+field('item-title-'+i,'Title / question',x.title)+field('item-text-'+i,'Text / answer',x.text,'textarea')+field('item-image-'+i,'Image URL',x.image)+field('item-alt-'+i,'Alt description',x.alt)+'<button class="btn secondary small" type="button" data-delete-item="'+i+'">Remove item</button></div>').join('')+'</div><button class="btn secondary small" id="add-item" type="button">Add item +</button>';}content+='<div class="form-actions">'+'<button id="duplicate-block" class="btn secondary" type="button">Duplicate section</button>'+'<button id="delete-block" class="btn danger" type="button">Delete section</button></div></form>';$('#block-editor').innerHTML=content;hydrateImageControls(b);$('#block-form').onsubmit=e=>e.preventDefault();$('#delete-block').onclick=()=>{if(!confirm('Delete this section from the draft? Published content remains until you publish.'))return;pageState.content.blocks.splice(selectedBlock,1);selectedBlock=Math.max(0,selectedBlock-1);renderEditor();};$('#duplicate-block').onclick=()=>{captureBlock();const copy=structuredClone(b);copy.id=crypto.randomUUID();if(copy.type==='existing')copy.sourceId=b.sourceId||b.id;copy.label+=' copy';pageState.content.blocks.splice(selectedBlock+1,0,copy);selectedBlock++;renderEditor();};if(b.type!=='existing'){$('#add-item').onclick=()=>{captureBlock();b.props.items.push({title:'New item',text:'',image:'',alt:'',url:'/fleet.html'});renderBlock();};document.querySelectorAll('[data-delete-item]').forEach(button=>button.onclick=()=>{captureBlock();b.props.items.splice(Number(button.dataset.deleteItem),1);renderBlock();});}}
 function captureBlock(){const form=$('#block-form'),b=pageState?.content.blocks[selectedBlock];if(!form||!b)return;const d=Object.fromEntries(new FormData(form));b.hidden=form.elements.hidden.checked;b.background=d.background;b.alignment=d.alignment||'original';if(b.type==='existing')for(const f of b.fields){f.text=d[f.key];if(f.url!==undefined){f.url=d[f.key+'-url'];if(f.tag==='img'){f.fit=d[f.key+'-url-fit'];f.focalX=Number(d[f.key+'-url-x']);f.focalY=Number(d[f.key+'-url-y']);}}}else{const items=b.props.items.map((x,i)=>({...x,title:d['item-title-'+i],text:d['item-text-'+i],image:d['item-image-'+i],fit:d['item-image-'+i+'-fit'],focalX:Number(d['item-image-'+i+'-x']),focalY:Number(d['item-image-'+i+'-y']),alt:d['item-alt-'+i]}));b.props={...b.props,title:d.title,text:d.text,image:d.image,fit:d['image-fit'],focalX:Number(d['image-x']),focalY:Number(d['image-y']),alt:d.alt,button:d.button,url:d.url,alignment:d.alignment,carIds:d.carIds.split(',').map(x=>Number(x.trim())).filter(x=>Number.isSafeInteger(x)&&x>0),items};}}
 async function saveDraft(){captureBlock();const r=await api('/api/admin/pages/'+pageState.slug,'PATCH',{revision:pageState.revision,content:pageState.content});pageState={...r.page,revisions:pageState.revisions};renderEditor();notice('Draft saved. Public content is unchanged until publishing.');}
 views.seo=async()=>{const r=await api('/api/admin/seo');$('#workspace-content').innerHTML='<section class="panel"><label>Page<select id="seo-choice">'+r.pages.map(p=>'<option value="'+p.slug+'">'+esc(p.file)+'</option>').join('')+'</select></label><div id="seo-editor"></div></section>';const render=()=>{const p=r.pages.find(p=>p.slug===$('#seo-choice').value),s=p.content.seo;$('#seo-editor').innerHTML='<form id="seo-form" class="form-grid">'+field('title','Page title',s.title)+field('slug','Friendly slug',s.slug)+field('description','Meta description',s.description,'textarea',true)+field('canonical','Canonical local path',s.canonical)+field('ogImage','Open Graph image URL',s.ogImage)+check('index','Allow search engine indexing',s.index)+check('structured','Include supported AutoRental structured data',s.structured)+'<div class="form-actions full"><button class="btn" type="submit">Save SEO draft</button><button class="btn secondary" type="button" id="seo-publish">Publish saved SEO</button><a class="btn secondary" href="/sitemap.xml" target="_blank">View sitemap</a></div></form>';formHandler($('#seo-form'),async(d,f)=>{const saved=await api('/api/admin/seo/'+p.slug,'PATCH',{revision:p.revision,seo:{...d,index:f.elements.index.checked,structured:f.elements.structured.checked}});Object.assign(p,saved.page);render();});$('#seo-publish').onclick=()=>action(async()=>{if(!confirm('Publish the saved page draft, including SEO?'))return;await api('/api/admin/pages/'+p.slug+'/publish','POST',{revision:p.revision,confirm:true});await views.seo();notice('SEO published. Sitemap updated.');});};$('#seo-choice').onchange=render;render();};
 function brandUpload(name,label,url,theme='light'){return '<div class="brand-upload"><h3>'+esc(label)+'</h3><div class="brand-preview brand-preview-'+theme+'" id="'+name+'-preview">'+(url?'<img src="'+esc(url)+'" alt="'+esc(label)+' preview">':'<span>No image · text branding</span>')+'</div><input type="hidden" name="'+name+'" value="'+esc(url||'')+'"><label class="brand-file">Upload '+esc(label.toLowerCase())+'<input type="file" data-brand-upload="'+name+'" accept="image/png,image/jpeg,image/webp"></label><button class="btn secondary small" type="button" data-brand-remove="'+name+'">Remove image</button><p class="muted">PNG, JPEG or WebP · optimized to 1 MB. Save settings to publish.</p></div>';}
 views.settings=async()=>{const r=await api('/api/admin/settings'),s=r.settings,p=r.policy;$('#workspace-content').innerHTML='<section class="panel"><h2>Business & website</h2><form id="settings-form"><div class="form-grid">'+field('name','Business name',s.name||'MZG Car Rental')+field('email','Business email',s.email||'contact.zulqurnain@gmail.com','email')+field('phone','Phone',s.phone||'+923025184681')+field('whatsapp','WhatsApp digits',s.whatsapp||'923025184681')+field('address','Lahore address',s.address||'Lahore, Punjab, Pakistan')+field('hours','Opening hours',s.hours)+select('publicDisplayPolicy','Fleet display before dates are selected',s.publicDisplayPolicy||'catalog',['catalog','available-now'])+'<div class="full branding-grid">'+brandUpload('headerLogo','Header logo',s.headerLogo??s.logo??'')+brandUpload('footerLogo','Footer logo',s.footerLogo??s.logo??'','dark')+brandUpload('favicon','Favicon',s.favicon||'')+'</div>'+field('footer','Footer description',s.footer,'textarea',true)+field('pickupLocations','Pickup locations — one per line',(s.pickupLocations||[]).join('\n'),'textarea',true)+field('navigation','Navigation — label | URL per line',(s.navigation||[]).map(n=>n.label+' | '+n.url).join('\n'),'textarea',true)+field('social','Social links — label | URL per line',(s.social||[]).map(n=>n.label+' | '+n.url).join('\n'),'textarea',true)+field('terms','Additional rental terms',s.terms,'textarea',true)+'</div><h2>Booking rules</h2><div class="form-grid">'+field('includedKmPerDay','Included km / day',p.includedKmPerDay,'number')+field('cancellationNoticeHours','Free cancellation notice (hours)',p.cancellationNoticeHours,'number')+field('minimumAge','Minimum age',p.minimumAge,'number')+Object.entries(p.categories).map(([k,v])=>field(k+'-deposit',k+' deposit (PKR)',v.deposit,'number')+field(k+'-extra',k+' extra km (PKR)',v.extraKm,'number')).join('')+'</div><p class="muted">Currency: PKR · Primary accent: #FF6900. No SMTP credentials or other secrets belong in CMS settings.</p><button class="btn" type="submit">Save website settings</button></form></section>';bindBrandUploads();formHandler($('#settings-form'),async d=>{const lines=v=>v.split('\n').map(x=>x.trim()).filter(Boolean),links=v=>lines(v).map(x=>{const [label,url]=x.split('|').map(x=>x.trim());return {label,url};});const settings={...s,...d,presentation:{...s.presentation,font:d['p-font'],emailComposeMode:d['p-emailComposeMode'],supportEnabled:$('#settings-form').elements['p-supportEnabled'].checked,supportLabel:d['p-supportLabel'],copyright:d['p-copyright'],footerGroups:[0,1,2].map(i=>({title:d['p-group-'+i],links:links(d['p-links-'+i])})).filter(g=>g.title&&g.links.length)},logo:'',navigation:links(d.navigation),social:links(d.social),pickupLocations:lines(d.pickupLocations)},policy={...p,includedKmPerDay:d.includedKmPerDay,cancellationNoticeHours:d.cancellationNoticeHours,minimumAge:d.minimumAge,categories:Object.fromEntries(Object.keys(p.categories).map(k=>[k,{deposit:d[k+'-deposit'],extraKm:d[k+'-extra']}]))};await api('/api/admin/settings','PATCH',{settings,policy});});};
 function bindBrandUploads(){let pending=0;document.querySelectorAll('[data-brand-upload]').forEach(input=>input.addEventListener('change',()=>action(async()=>{const file=input.files[0];if(!file)return;const submit=$('#settings-form button[type=submit]');pending++;submit.disabled=true;input.disabled=true;try{const r=await upload(file,file.name,'branding');$('#settings-form [name="'+input.dataset.brandUpload+'"]').value=r.url;$('#'+input.dataset.brandUpload+'-preview').innerHTML='<img src="'+esc(r.url)+'" alt="Logo preview">';notice('Image uploaded. Save website settings to publish it.');}finally{pending--;submit.disabled=pending>0;input.disabled=false;input.value='';}})));document.querySelectorAll('[data-brand-remove]').forEach(button=>button.onclick=()=>{const key=button.dataset.brandRemove;$('#settings-form [name="'+key+'"]').value='';$('#'+key+'-preview').innerHTML='<span>No image · text branding</span>';notice('Image removed from this draft. Save settings to publish.');});}
 views.maintenance=async()=>{const r=await api('/api/admin/maintenance'),m=r.maintenance;$('#workspace-content').innerHTML='<section class="panel"><h2>Availability controls</h2><form id="maintenance-form">'+check('enabled','Show maintenance page to public visitors',m.enabled)+check('bookingsDisabled','Pause new online rental requests',m.bookingsDisabled)+field('message','Maintenance message',m.message,'textarea')+field('until','Expected restoration (optional)',m.until)+'<p class="muted">Administrator sign-in and workspace remain accessible. This is enforced by the server.</p><button class="btn" type="submit">Save maintenance settings</button></form></section>';formHandler($('#maintenance-form'),async(d,f)=>{const enabled=f.elements.enabled.checked;if(enabled&&!confirm('Activate public maintenance mode? Admin access will remain available.'))return;await api('/api/admin/maintenance','PATCH',{...d,enabled,bookingsDisabled:f.elements.bookingsDisabled.checked,confirm:true});});};
 views.security=async()=>{if(!identity.mfaEnabled){$('#workspace-content').innerHTML='<section class="panel"><h2>Set up authenticator protection</h2><p>Admin account: <strong>'+esc(identity.user.email)+'</strong>.</p><p>This code does not arrive by email. Google Authenticator or Microsoft Authenticator generates it after you add the setup key. Email delivery configuration is separate.</p><form id="mfa-setup">'+field('password','Confirm current password','','password')+'<button class="btn" type="submit">Start authenticator setup</button></form><div id="mfa-enrollment"></div></section>';formHandler($('#mfa-setup'),async d=>{const r=await api('/api/admin/mfa/setup','POST',d);$('#mfa-enrollment').innerHTML='<p style="margin-top:24px"><strong>Recommended:</strong> Google Authenticator → + → Scan QR code. Remove the previous MZG entry if it used a different key.</p><img src="'+esc(r.qr)+'" alt="Scan to add MZG to your authenticator" width="240" height="240" style="max-width:100%;height:auto"><p class="muted">Setup expires at '+esc(new Date(r.expiresAt).toLocaleTimeString())+'. Starting again before expiry keeps the same key. Enable automatic date/time on your phone.</p><p>In Google Authenticator: tap + → Enter a setup key. Name: MZG Admin. Choose Time based, then add this key:</p><code style="overflow-wrap:anywhere">'+esc(r.secret)+'</code><p class="muted">MZG Car Rental · Time based · SHA1 · 6 digits · 30 seconds. Do not share this key.</p><form id="mfa-confirm">'+field('code','6-digit code shown in your Authenticator app')+'<button class="btn" type="submit">Enable MFA</button></form>';formHandler($('#mfa-confirm'),async d=>{await api('/api/admin/mfa/confirm','POST',d);location.assign('/admin/dashboard');});return 'Scan the QR code in your authenticator app, then enter the code shown for MZG.';});return;}if(identity.role!=='owner'){$('#workspace-content').innerHTML='<section class="panel"><h2>Authenticator enabled</h2><p>Your administrator sessions require password and authenticator verification.</p><a class="btn secondary" href="/account-settings.html">Change password</a></section>';return;}const r=await api('/api/admin/security');$('#workspace-content').innerHTML='<section class="panel"><h2>Administrator access</h2>'+table(['Account','Role','MFA','Permissions'],r.accounts.map(a=>'<tr><td>'+esc(a.name)+'<br>'+esc(a.email)+'</td><td>'+esc(a.role)+'</td><td>'+(a.mfa?'Enabled':'Enrollment needed')+'</td><td>'+esc(a.role==='owner'?'Owner full access':JSON.parse(a.permissions).join(', ')||'None')+'</td></tr>'))+'<h3 style="margin-top:32px">Assign an existing account</h3><form id="role-form" class="form-grid">'+field('email','Existing account email','','email')+select('role','Role','staff',['staff','admin','customer'])+'<div class="full">'+r.permissions.filter(x=>!['notifications','settings','maintenance','security','backups'].includes(x)).map(p=>check('permission-'+p,labels[p],false)).join('')+'</div>'+check('sendInvite','Send a one-use email invitation instead',false)+'<button class="btn" type="submit">Assign / invite</button></form><p class="muted">No public administrator registration. The owner cannot be demoted through this panel. Assigned accounts must enroll their own authenticator.</p></section><section class="panel"><h2>Security & activity log</h2>'+table(['When','Actor','Action','Resource','Result'],r.logs.map(l=>'<tr><td>'+esc(new Date(l.created_at).toLocaleString())+'</td><td>'+esc(l.actor||'System / unauthenticated')+'</td><td>'+esc(l.action)+'</td><td>'+esc(l.resource)+'</td><td>'+(l.success?'Success':'Denied')+'</td></tr>'))+'</section>';formHandler($('#role-form'),async(d,f)=>{if(!confirm('Assign these explicit permissions and revoke the account’s existing sessions?'))return;const permissions=r.permissions.filter(p=>f.elements['permission-'+p]?.checked);await api(f.elements.sendInvite.checked?'/api/admin/invitations':'/api/admin/roles','POST',{email:d.email,role:d.role,permissions,confirm:true});await views.security();});};
 views.backups=async()=>{const r=await api('/api/admin/backups');if(r.backend==='postgres'){$('#workspace-content').innerHTML='<section class="panel"><h2>PostgreSQL backups</h2><p>Your database is hosted privately in Supabase. Use a private pg_dump export and verify a restore in a separate database before production restoration.</p><p>Local SQLite snapshot controls do not apply to this hosted database. Scheduled backups require an external scheduler; serverless temporary storage is not a backup.</p></section>';return;}$('#workspace-content').innerHTML='<section class="panel"><h2>Verified database backups</h2><p>Snapshots include customers, booking records, CMS content and uploaded images. Keep downloads private.</p><p class="muted">Scheduled interval: '+(r.scheduledHours?r.scheduledHours+' hours':'not configured')+'. The database snapshot needs the original MFA encryption key to restore authenticator access.</p><button class="btn" id="make-backup">Create verified backup</button></section><section class="panel">'+(r.backups.length?table(['Created','Size','Integrity hash',''],r.backups.map(b=>'<tr><td>'+esc(new Date(b.created_at).toLocaleString())+'</td><td>'+Math.round(b.size/1024)+' KB</td><td><code>'+esc(b.sha256.slice(0,20))+'…</code></td><td><a class="btn secondary small" href="/api/admin/backups/'+b.id+'">Download</a></td></tr>')):empty('No backups created'))+'</section><section class="panel"><h2>Restore safely</h2><p>Restoration is performed offline with <code>node restore-backup.cjs PATH SHA256 --confirm-restore</code> after stopping the Node server. The command verifies integrity, preserves the current database, restores the snapshot and revokes sessions. See ADMIN_SETUP.md before restoring.</p></section>';$('#make-backup').onclick=()=>action(async()=>{if(!confirm('Create a private database snapshot including customer information?'))return;const r=await api('/api/admin/backups','POST',{confirm:true});await views.backups();notice(r.message);});};
 views.notifications=async()=>{const r=await api('/api/admin/notifications');$('#workspace-content').innerHTML='<section class="panel"><h2>Email delivery</h2><p>'+pill(r.configured?'Provider configured':'Setup required')+' <span class="muted">'+esc(r.provider)+'</span></p><p>Credentials are configured in private hosting environment settings. They are never stored in CMS fields.</p><p class="muted">Vercel Hobby reminders run daily, not hourly. A provider-accepted message still needs inbox receipt confirmation.</p><button class="btn" id="test-email" '+(!r.configured?'disabled':'')+'>Send test to my owner inbox</button> <button class="btn secondary" id="process-emails" '+(!r.configured?'disabled':'')+'>Process due reminders / retries</button></section><div class="stats-grid">'+r.counts.map(c=>'<article class="stat-card"><span>'+esc(c.status)+'</span><strong>'+c.count+'</strong></article>').join('')+'</div><section class="panel"><h2>Notification history</h2>'+table(['Message','Status','Attempts','Created','Provider error'],r.recent.map(j=>'<tr><td>'+esc(j.subject)+'</td><td>'+pill(j.status)+'</td><td>'+j.attempts+'</td><td>'+esc(new Date(j.created_at).toLocaleString())+'</td><td>'+esc(j.last_error||'—')+'</td></tr>'))+'</section>';$('#test-email').onclick=()=>action(async()=>{if(!confirm('Send one real test email to your owner account email?'))return;const result=await api('/api/admin/notifications/test','POST',{});notice(result.message);});$('#process-emails').onclick=()=>action(async()=>{const result=await api('/api/admin/notifications/process','POST',{});await views.notifications();notice('Provider accepted '+result.sent+' message(s); '+result.failed+' delivery attempt(s) failed.');});};
 views.availability=async()=>{
 const today=new Date(Date.now()+5*3600000).toISOString().slice(0,10),start=new URLSearchParams(location.search).get('start')||today,end=new URLSearchParams(location.search).get('end')||new Date(Date.now()+14*86400000).toISOString().slice(0,10);const r=await api('/api/admin/availability?'+new URLSearchParams({start:start+'T00:00',end:end+'T23:59'}));
 const dates=Array.from({length:Math.min(31,Math.ceil((new Date(end)-new Date(start))/86400000)+1)},(_,i)=>new Date(new Date(start+'T00:00:00Z').getTime()+i*86400000).toISOString().slice(0,10));
 const cell=(v,d)=>{const from=d+'T00:00:00+05:00',to=d+'T23:59:59+05:00',b=r.bookings.find(b=>b.car_id===v.id&&['Confirmed','Active'].includes(b.status)&&(!b.returned_at)&&((b.pickup_at<new Date(to).toISOString()&&b.return_at>new Date(from).toISOString())||b.status==='Active')),m=r.maintenance.find(m=>m.car_id===v.id&&m.starts_at<new Date(to).toISOString()&&m.ends_at>new Date(from).toISOString());return '<td class="timeline-cell '+(b?'timeline-booked':m||['Maintenance','Unavailable'].includes(v.state)?'timeline-blocked':'timeline-free')+'" title="'+esc(b?b.reference+' · '+b.status:m?m.reason:v.state)+'">'+(b?esc(b.status):m?'Service':'·')+'</td>';};
 $('#workspace-content').innerHTML='<section class="panel"><div class="panel-heading"><div><h2>Fleet availability</h2><p class="muted">Pending requests do not reserve inventory. Active rentals remain blocked until actual return is recorded.</p></div><span class="status-pill">'+r.overdue.length+' overdue</span></div><form id="availability-filter" class="form-grid">'+field('start','From',start,'date')+field('end','Through',end,'date')+'<button class="btn" type="submit">Search availability</button></form></section>'+(r.overdue.length?'<section class="panel overdue-panel"><h2>Return follow-up required</h2>'+r.overdue.map(b=>'<p>'+esc(b.reference+' · '+b.car_name)+' — scheduled return '+esc(new Date(b.return_at).toLocaleString())+'</p>').join('')+'</section>':'')+'<section class="panel"><h2>Vehicle timeline</h2><p class="muted">Timeline shows up to 31 days. Orange: reserved / on rent · Gray: maintenance / unavailable · White: open for this period.</p><div class="table-scroll"><table class="admin-table availability-table"><thead><tr><th>Vehicle / state</th>'+dates.map(d=>'<th>'+esc(d.slice(5))+'</th>').join('')+'</tr></thead><tbody>'+r.vehicles.map(v=>'<tr><th scope="row">'+esc(v.name)+'<br><small>'+esc(v.reference+' · '+v.state)+'</small></th>'+dates.map(d=>cell(v,d)).join('')+'</tr>').join('')+'</tbody></table></div></section><section class="panel"><h2>Rental operations</h2>'+table(['Reference','Car','Status','Due','Actions'],r.bookings.map(b=>'<tr><td>'+esc(b.reference)+'</td><td>'+esc(b.car_name)+'</td><td>'+pill(b.status)+'</td><td>'+esc(new Date(b.return_at).toLocaleString())+'</td><td>'+(['Confirmed','Active'].includes(b.status)?'<button class="btn small secondary" data-extend="'+b.id+'">Extend</button> ':'')+(b.status==='Confirmed'?'<button class="btn small" data-pickup="'+b.id+'">Record pickup</button>':b.status==='Active'?'<button class="btn small" data-return="'+b.id+'">Record return</button>':'Awaiting review')+'</td></tr>'))+'</section><section class="panel"><h2>Schedule maintenance</h2><form id="maintenance-block" class="form-grid"><label>Physical vehicle<select name="carId">'+r.vehicles.map(v=>'<option value="'+v.id+'">'+esc(v.reference+' · '+v.name)+'</option>').join('')+'</select></label>'+field('startsAt','Start (Pakistan time)',start+'T09:00','datetime-local')+field('endsAt','End (Pakistan time)',end+'T18:00','datetime-local')+field('reason','Reason','','textarea')+'<button class="btn" type="submit">Block maintenance period</button></form>'+table(['Car','Period','Reason',''],r.maintenance.map(m=>'<tr><td>'+esc(r.vehicles.find(v=>v.id===m.car_id)?.name||m.car_id)+'</td><td>'+esc(new Date(m.starts_at).toLocaleString())+' – '+esc(new Date(m.ends_at).toLocaleString())+'</td><td>'+esc(m.reason)+'</td><td><button class="btn secondary small" data-release="'+m.id+'">Remove block</button></td></tr>'))+'</section>';
 formHandler($('#availability-filter'),async d=>{if(d.end<d.start)throw Error('Choose an end date after the start date.');location.assign('/admin/availability?'+new URLSearchParams(d));});formHandler($('#maintenance-block'),async d=>{if(!confirm('Block this vehicle for the maintenance period?'))return;await api('/api/admin/availability/maintenance','POST',d);await views.availability();});
 document.querySelectorAll('[data-return],[data-pickup],[data-extend]').forEach(button=>button.onclick=()=>action(async()=>{const id=button.dataset.return||button.dataset.pickup||button.dataset.extend;if(button.dataset.extend){dialog('Extend rental','<form id="extend-rental">'+field('returnAt','New return (Pakistan time)',end+'T18:00','datetime-local')+'<p class="muted">This checks conflicts. Review and update the quotation separately.</p><button class="btn" type="submit">Save extension</button></form>');formHandler($('#extend-rental'),async d=>{await api('/api/admin/availability/bookings/'+id,'POST',{action:'extend',returnAt:d.returnAt});$('#admin-dialog').close();await views.availability();});return;}const operation=button.dataset.return?'return':'pickup';if(!confirm(operation==='return'?'Confirm this car has actually returned and has been checked in?':'Confirm actual vehicle pickup?'))return;await api('/api/admin/availability/bookings/'+id,'POST',{action:operation,confirm:true});await views.availability();}));document.querySelectorAll('[data-release]').forEach(b=>b.onclick=()=>action(async()=>{if(!confirm('Remove this maintenance block?'))return;await api('/api/admin/availability/maintenance/'+b.dataset.release,'DELETE',{confirm:true});await views.availability();}));
 };
 const settingsView=views.settings;
 views.settings=async()=>{await settingsView();$('#settings-form button[type=submit]').disabled=true;const {settings:s,defaults}=await api('/api/admin/settings'),p=s.presentation||{},groups=p.footerGroups?.length?p.footerGroups:defaults.footerGroups;$('#settings-form').insertAdjacentHTML('afterbegin','<section class="presentation-settings"><h2>Presentation & shared content</h2><p class="muted">Page headings, images, buttons, labels and sections are managed in Website pages. These controls apply to public and customer pages.</p><div class="toolbar"><a class="btn secondary" href="/admin/pages">Edit website sections</a><a class="btn secondary" href="/admin/fleet">Manage car details</a><a class="btn secondary" href="/admin/seo">Manage page SEO</a></div><div class="form-grid">'+select('p-font','Website font',p.font||'brand',['brand','system','arial'])+select('p-emailComposeMode','Email link behavior',p.emailComposeMode||'chooser',['chooser','gmail','app'])+check('p-supportEnabled','Show floating WhatsApp button',p.supportEnabled!==false)+field('p-supportLabel','WhatsApp accessibility label',p.supportLabel||'Chat on WhatsApp')+field('p-copyright','Copyright text ({year} updates automatically)',p.copyright||'','text',true)+[0,1,2].map(i=>field('p-group-'+i,'Footer group '+(i+1)+' heading',groups[i]?.title||'')+field('p-links-'+i,'Footer group '+(i+1)+' — label | URL per line',(groups[i]?.links||[]).map(l=>l.label+' | '+l.url).join('\n'),'textarea')).join('')+'</div><p class="muted">Leave footer groups empty to retain the current links. Keep credentials and executable code out of content settings.</p></section>');$('#settings-form button[type=submit]').disabled=false;};
 const notificationView=views.notifications;
 views.notifications=async()=>{await notificationView();const r=await api('/api/admin/notifications/audience');$('#workspace-content').insertAdjacentHTML('afterbegin','<section class="panel"><h2>Send customer notification</h2><p class="muted">Create a website notification, an email update, or both. Email goes only to verified customers who allow administrator email updates. Essential booking/security emails are unaffected by that preference.</p><form id="announcement-form">'+field('title','Notification title')+field('body','Message','','textarea')+field('url','Website destination','/dashboard.html')+'<div class="form-grid">'+check('website','Website bell notification',true)+check('email','Email notification',false)+check('allCustomers','All active customers',false)+'</div><label>Find customer<input id="notice-customer-search" type="search" placeholder="Name or email"></label><div class="recipient-grid">'+r.customers.map(u=>'<label data-recipient-search="'+esc((u.name+' '+u.email).toLowerCase())+'"><input type="checkbox" name="recipient" value="'+esc(u.id)+'"> '+esc(u.name)+' <small>'+esc(u.email)+' · '+(u.verified_at?'Verified':'Email not verified')+'</small></label>').join('')+'</div><p class="muted">Up to 250 customers per announcement. Emails are queued with retries; larger groups may require additional processing batches.</p><button class="btn" type="submit">Review notification</button></form></section><section class="panel"><h2>Customer announcement history</h2>'+table(['Title','Website recipients','Email recipients','Created'],r.history.map(n=>'<tr><td>'+esc(n.title)+'</td><td>'+n.website_count+'</td><td>'+n.email_count+'</td><td>'+esc(new Date(n.created_at).toLocaleString())+'</td></tr>'))+'</section>');$('#notice-customer-search').oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('[data-recipient-search]').forEach(n=>n.hidden=!n.dataset.recipientSearch.includes(q));};formHandler($('#announcement-form'),async(d,f)=>{const payload={title:d.title,body:d.body,url:d.url,website:f.elements.website.checked,email:f.elements.email.checked,allCustomers:f.elements.allCustomers.checked,userIds:[...f.querySelectorAll('[name=recipient]:checked')].map(n=>n.value),requestId:crypto.randomUUID()};const counts=await api('/api/admin/notifications/preview','POST',payload);dialog('Review customer notification','<h3>'+esc(payload.title)+'</h3><p class="announcement-preview">'+esc(payload.body)+'</p><p>Website: '+counts.website+' · Email: '+counts.email+' · Email skipped: '+counts.skippedEmail+'</p><p class="muted">Sending creates persistent customer notifications and queues real emails.</p><button class="btn" id="confirm-announcement">Send this notification</button>');$('#confirm-announcement').onclick=()=>action(async()=>{const b=$('#confirm-announcement');b.disabled=true;try{const result=await api('/api/admin/notifications/send','POST',{...payload,confirm:true});$('#admin-dialog').close();await views.notifications();notice(result.website+' website notifications created; '+result.email+' emails queued. '+(result.delivery?.sent||0)+' queue messages accepted by the provider during this request.');}catch(e){b.disabled=false;throw e;}});return 'Review the notification before confirming.';});};
 const presentationView=views.settings;
